/* D365 CE Roster profile builder. Hand-written; the page around it is generated by scripts/build-site.py.
 *
 * Everything runs in the browser. The form is read into a plain state object, turned into a profile object, checked
 * against the profile schema (embedded in the page) and written out as YAML by a real serialiser, so the output always
 * has the structure the schema expects. The pure functions are exported for scripts/check-profile-builder.py, which
 * runs them in Node.js and validates the YAML they produce.
 */
(function (root) {
  "use strict";

  var DIRECTIONS = ["inbound", "outbound", "both"];
  var FREQUENCIES = ["real-time", "near-real-time", "scheduled", "manual"];
  var CHANNELS = ["email", "phone", "chat", "messaging", "social", "web-portal"];
  var FORMATS = ["docx", "xlsx", "md"];
  var ROLE_WORDS = /\b(analyst|architect|consultant|developer|engineer|lead|manager|owner|admin|administrator|tester|sponsor|person|partner|trainer|specialist|designer|director|officer|champion|user|team|member)\b/i;

  // ------------------------------------------------------------------ helpers
  function str(v) { return (v === undefined || v === null) ? "" : String(v).trim(); }
  function int(v, min, max, fallback) {
    var n = parseInt(v, 10);
    if (isNaN(n)) return fallback;
    if (min !== undefined && n < min) n = min;
    if (max !== undefined && n > max) n = max;
    return n;
  }
  function list(s) { return str(s).split(",").map(function (x) { return x.trim(); }).filter(Boolean); }
  function lines(s) { return str(s).split(/\r?\n/).map(function (x) { return x.trim(); }).filter(Boolean); }
  function put(obj, key, value) {
    // Leave out empty optional values, so the profile carries only what the user said.
    if (value === undefined || value === null || value === "") return;
    if (Array.isArray(value) && value.length === 0) return;
    obj[key] = value;
  }

  // ------------------------------------------------------------------ state -> profile
  function buildProfile(s) {
    var p = { schema_version: "0.1" };

    var org = { name: str(s.org.name), size_staff: int(s.org.staff, 1, undefined, 1) };
    put(org, "sector", str(s.org.sector));
    put(org, "countries", list(s.org.countries));
    put(org, "legal_entities", int(s.org.entities, 1, undefined, undefined));
    put(org, "regulatory_context", list(s.org.regulatory));
    p.organisation = { name: org.name };
    ["sector", "size_staff", "countries", "legal_entities", "regulatory_context"].forEach(function (k) {
      if (k in org) p.organisation[k] = org[k];
    });

    var goals = { outcomes: lines(s.goals.outcomes) };
    put(goals, "success_measures", lines(s.goals.measures));
    put(goals, "target_go_live", str(s.goals.goLive));
    put(goals, "budget_band", str(s.goals.budget));
    p.goals = goals;

    var m = s.modules;
    function mod(x, extra) {
      var o = { in_scope: !!x.on };
      if (x.on) {
        put(o, "users", int(x.users, 0, undefined, undefined));
        if (extra) extra(o);
      }
      put(o, "notes", str(x.notes));
      return o;
    }
    p.modules = {
      sales: mod(m.sales),
      marketing: mod(m.marketing, function (o) { put(o, "contacts", int(m.marketing.contacts, 0, undefined, undefined)); }),
      customer_service: mod(m.customer_service, function (o) {
        put(o, "channels", (m.customer_service.channels || []).filter(function (c) { return CHANNELS.indexOf(c) >= 0; }));
      }),
      field_service: mod(m.field_service, function (o) { put(o, "technicians", int(m.field_service.technicians, 0, undefined, undefined)); })
    };

    var e = s.estate, estate = {};
    put(estate, "current_crm", str(e.crm));
    put(estate, "legacy_systems", (e.legacy || []).filter(function (l) { return str(l.name); }).map(function (l) {
      var o = { name: str(l.name) };
      put(o, "purpose", str(l.purpose));
      if (l.retire !== undefined && l.retire !== null) o.retire = !!l.retire;
      put(o, "records_estimate", int(l.records, 0, undefined, undefined));
      return o;
    }));
    put(estate, "erp", str(e.erp));
    put(estate, "email_and_calendar", str(e.email));
    put(estate, "telephony", str(e.telephony));
    put(estate, "data_sources", list(e.dataSources));
    put(estate, "integrations", (e.integrations || []).filter(function (i) { return str(i.system); }).map(function (i) {
      var o = { system: str(i.system) };
      if (DIRECTIONS.indexOf(i.direction) >= 0) o.direction = i.direction;
      if (FREQUENCIES.indexOf(i.frequency) >= 0) o.frequency = i.frequency;
      put(o, "purpose", str(i.purpose));
      return o;
    }));
    if (e.m365 !== undefined && e.m365 !== null) estate.microsoft_365 = !!e.m365;
    put(estate, "licences", list(e.licences));
    put(estate, "environments", list(e.environments));
    if (Object.keys(estate).length) p.estate = estate;

    var useAliases = !!s.prefs.aliases;
    p.team = (s.team || []).map(function (t) {
      var o = { alias: str(t.alias) };
      if (!useAliases) put(o, "name", str(t.name));
      put(o, "current_role", str(t.role));
      o.availability_percent = int(t.availability, 0, 100, 0);
      o.internal = !!t.internal;
      o.skills = (t.skills || []).filter(function (k) { return str(k.skill); }).map(function (k) {
        return { skill: str(k.skill), level: str(k.level) };
      });
      return o;
    });

    var c = s.constraints, constraints = {};
    var partner = { engaged: !!c.partner };
    if (c.partner) put(partner, "scope", list(c.partnerScope));
    constraints.partner = partner;
    put(constraints, "compliance", list(c.compliance));
    put(constraints, "change_freezes", lines(c.freezes));
    put(constraints, "known_risks", lines(c.risks));
    p.constraints = constraints;

    p.preferences = {
      use_aliases: useAliases,
      edition: str(s.prefs.edition) || "auto",
      output_formats: (s.prefs.formats || []).filter(function (f) { return FORMATS.indexOf(f) >= 0; })
    };
    return p;
  }

  // ------------------------------------------------------------------ YAML
  function scalar(v) {
    if (typeof v === "string") return JSON.stringify(v); // a JSON string is a valid YAML double-quoted scalar
    if (typeof v === "number" || typeof v === "boolean") return String(v);
    if (v === null || v === undefined) return "null";
    throw new Error("Unsupported value");
  }
  function isScalar(v) { return v === null || typeof v !== "object"; }

  function emit(v, indent) {
    var pad = new Array(indent + 1).join(" "), out = [];
    if (Array.isArray(v)) {
      v.forEach(function (item) {
        if (isScalar(item)) { out.push(pad + "- " + scalar(item)); return; }
        if (Array.isArray(item) ? !item.length : !Object.keys(item).length) {
          out.push(pad + "- " + (Array.isArray(item) ? "[]" : "{}")); return;
        }
        var inner = emit(item, indent + 2);
        inner[0] = pad + "- " + inner[0].slice(indent + 2);
        out = out.concat(inner);
      });
      return out;
    }
    Object.keys(v).forEach(function (k) {
      var x = v[k];
      if (isScalar(x)) out.push(pad + k + ": " + scalar(x));
      else if (Array.isArray(x) && !x.length) out.push(pad + k + ": []");
      else if (!Array.isArray(x) && !Object.keys(x).length) out.push(pad + k + ": {}");
      else { out.push(pad + k + ":"); out = out.concat(emit(x, indent + 2)); }
    });
    return out;
  }
  function toYaml(profile) {
    return "# D365 CE Roster organisation profile, made with the profile builder.\n" +
      "# Keep it in your own storage. It describes your organisation and team; do not publish it.\n" +
      emit(profile, 0).join("\n") + "\n";
  }

  // ------------------------------------------------------------------ schema check (the subset the profile schema uses)
  var LABELS = {
    "organisation.name": "Organisation name", "organisation.size_staff": "Staff",
    "goals.outcomes": "Outcomes", "goals.target_go_live": "Target go-live", "team": "Team"
  };
  function label(path) { return LABELS[path] || path; }

  function validate(value, sch, path, errors) {
    path = path || "";
    errors = errors || [];
    var t = sch.type;
    var ok = !t ||
      (t === "object" && value !== null && typeof value === "object" && !Array.isArray(value)) ||
      (t === "array" && Array.isArray(value)) ||
      (t === "string" && typeof value === "string") ||
      (t === "integer" && typeof value === "number" && Math.floor(value) === value) ||
      (t === "boolean" && typeof value === "boolean");
    if (!ok) { errors.push(label(path) + ": expected " + t); return errors; }
    if (sch["enum"] && sch["enum"].indexOf(value) < 0) errors.push(label(path) + ": must be one of " + sch["enum"].join(", "));
    if (sch.pattern && typeof value === "string" && !new RegExp(sch.pattern).test(value)) errors.push(label(path) + ": not in the expected format");
    if (sch.minimum !== undefined && typeof value === "number" && value < sch.minimum) errors.push(label(path) + ": must be at least " + sch.minimum);
    if (sch.maximum !== undefined && typeof value === "number" && value > sch.maximum) errors.push(label(path) + ": must be at most " + sch.maximum);
    if (t === "string" && sch.minLength && value.length < sch.minLength) errors.push(label(path) + ": is empty");
    if (t === "object") {
      (sch.required || []).forEach(function (r) { if (!(r in value)) errors.push(label(path ? path + "." + r : r) + ": is required"); });
      var props = sch.properties || {};
      Object.keys(value).forEach(function (k) {
        var p = path ? path + "." + k : k;
        if (props[k]) validate(value[k], props[k], p, errors);
        else if (sch.additionalProperties === false) errors.push(label(p) + ": is not part of the profile format");
      });
    }
    if (t === "array") {
      if (sch.minItems && value.length < sch.minItems) errors.push(label(path) + ": needs at least " + sch.minItems);
      value.forEach(function (item, i) { validate(item, sch.items || {}, path + "[" + i + "]", errors); });
    }
    return errors;
  }

  // Checks the schema cannot express: values the profile needs to be useful, and things worth a second look.
  function review(p, vocabIds) {
    var problems = [], checks = [];
    if (!str(p.organisation.name)) problems.push("Add the organisation's name, or an alias such as \"Org A\".");
    if (!p.goals.outcomes.length) problems.push("Add at least one outcome under Goals.");
    if (!p.team.length) problems.push("Add at least one person to the team.");
    var aliases = {};
    p.team.forEach(function (t, i) {
      var who = t.alias || ("Person " + (i + 1));
      if (!t.alias) problems.push("Give person " + (i + 1) + " an alias.");
      else if (aliases[t.alias.toLowerCase()]) problems.push("Two people share the alias \"" + t.alias + "\". Aliases must be unique.");
      aliases[(t.alias || "").toLowerCase()] = true;
      if (!t.skills.length) checks.push(who + " has no skills listed, so role mapping cannot propose them for any role.");
      var seen = {};
      t.skills.forEach(function (k) {
        if (vocabIds && vocabIds.indexOf(k.skill) < 0) problems.push(who + " lists \"" + k.skill + "\", which is not in the skills vocabulary.");
        if (seen[k.skill]) checks.push(who + " lists \"" + k.skill + "\" more than once.");
        seen[k.skill] = true;
      });
      if (p.preferences.use_aliases && /^[A-Z][a-z'\u2019-]+(\s+[A-Z][a-z'\u2019-]+)+$/.test(t.alias) && !ROLE_WORDS.test(t.alias)) {
        checks.push("\"" + t.alias + "\" looks like a person's name. \"Use aliases\" is on, so the alias appears in every document. " +
          "Use something like \"" + t.alias.split(/\s+/)[0] + " " + t.alias.split(/\s+/).slice(-1)[0].charAt(0) + "\" or a role-based alias, " +
          "or turn off \"Use aliases\" and put the name in the Name field.");
      }
    });
    var name = str(p.organisation.name);
    name.split(/\s+/).forEach(function (w) {
      if (/^[A-Z]{2,}[a-z]/.test(w)) checks.push("Check the spelling of \"" + w + "\" in the organisation name. It appears exactly as typed in every document.");
    });
    var est = p.estate || {};
    var known = [est.current_crm, est.erp, est.telephony, est.email_and_calendar]
      .concat((est.legacy_systems || []).map(function (l) { return l.name; }))
      .concat(est.data_sources || []).filter(Boolean);
    var norm = function (x) { return str(x).toLowerCase().replace(/[^a-z0-9]/g, ""); };
    (est.integrations || []).forEach(function (i) {
      var missing = [];
      if (!i.direction) missing.push("direction");
      if (!i.frequency) missing.push("frequency");
      if (!i.purpose) missing.push("purpose");
      var said = missing.length > 1 ? missing.slice(0, -1).join(", ") + " or " + missing[missing.length - 1] : missing[0];
      if (missing.length) checks.push("The \"" + i.system + "\" integration has no " + said +
        ". The integration inventory and test strategy will mark them \"To confirm\".");
      if (known.length && !known.some(function (k) { var a = norm(k), b = norm(i.system); return a && b && (a.indexOf(b) >= 0 || b.indexOf(a) >= 0); })) {
        checks.push("The integration \"" + i.system + "\" does not match any system named in the estate (" + known.join(", ") +
          "). If it is one of those, use the same name so the documents agree.");
      }
    });
    var anyModule = ["sales", "marketing", "customer_service", "field_service"].some(function (k) { return p.modules[k].in_scope; });
    if (!anyModule) problems.push("Select at least one module in scope.");
    if (!p.preferences.output_formats.length) problems.push("Choose at least one output format.");
    if (!(p.constraints.known_risks || []).length) checks.push("No known risks are listed. The RAID log will start with only the standard CRM risks and the \"To confirm\" items.");
    return { problems: problems, checks: checks };
  }

  var api = { buildProfile: buildProfile, toYaml: toYaml, validate: validate, review: review, DIRECTIONS: DIRECTIONS, FREQUENCIES: FREQUENCIES, CHANNELS: CHANNELS };
  if (typeof module !== "undefined" && module.exports) { module.exports = api; return; }
  root.ProfileBuilder = api;

  // ------------------------------------------------------------------ the page
  var dataEl = document.getElementById("builder-data");
  if (!dataEl) return;
  var DATA = JSON.parse(dataEl.textContent);
  var VOCAB_IDS = DATA.vocab.map(function (v) { return v.id; });
  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;" }[c]; }); };
  var options = function (values, blank) {
    return (blank ? "<option value=\"\">" + esc(blank) + "</option>" : "") +
      values.map(function (v) { return "<option>" + esc(v) + "</option>"; }).join("");
  };

  function addSkill(box, skill, level) {
    var r = document.createElement("div");
    r.className = "row skill";
    r.innerHTML = "<div><label>Skill</label><select class=\"sk\">" + DATA.vocab.map(function (v) {
      return "<option value=\"" + esc(v.id) + "\" title=\"" + esc(v.d) + "\">" + esc(v.id) + "</option>";
    }).join("") + "</select></div><div><label>Level</label><select class=\"lv\">" + options(DATA.levels) + "</select></div>" +
      "<div class=\"row-actions\"><button type=\"button\" class=\"secondary rmsk\">Remove skill</button></div>";
    box.appendChild(r);
    if (skill) r.querySelector(".sk").value = skill;
    if (level) r.querySelector(".lv").value = level;
    r.querySelector(".rmsk").onclick = function () { r.remove(); update(); };
  }

  function addPerson() {
    var n = document.querySelectorAll(".person").length + 1;
    var p = document.createElement("div");
    p.className = "person";
    p.innerHTML = "<div class=\"row\"><div><label>Alias</label><input type=\"text\" class=\"alias\" value=\"Person " + n + "\"></div>" +
      "<div class=\"name-field\"><label>Name (optional)</label><input type=\"text\" class=\"pname\" placeholder=\"Only used when aliases are off\"></div>" +
      "<div><label>Current role</label><input type=\"text\" class=\"role\"></div>" +
      "<div><label>Availability %</label><input type=\"number\" class=\"avail\" min=\"0\" max=\"100\" value=\"50\"></div>" +
      "<div><label><input type=\"checkbox\" class=\"internal\" checked> Internal staff</label></div></div>" +
      "<div class=\"skills\"></div><button type=\"button\" class=\"secondary addsk\">Add a skill</button> " +
      "<button type=\"button\" class=\"secondary rm\">Remove person</button>";
    $("team").appendChild(p);
    addSkill(p.querySelector(".skills"));
    p.querySelector(".addsk").onclick = function () { addSkill(p.querySelector(".skills")); update(); };
    p.querySelector(".rm").onclick = function () { p.remove(); update(); };
    syncNames();
  }

  function addIntegration() {
    var r = document.createElement("div");
    r.className = "row integration";
    r.innerHTML = "<div><label>System</label><input type=\"text\" class=\"isys\" list=\"systems\" placeholder=\"For example, the ERP\"></div>" +
      "<div><label>Direction</label><select class=\"idir\">" + options(DIRECTIONS, "Not sure yet") + "</select></div>" +
      "<div><label>Frequency</label><select class=\"ifreq\">" + options(FREQUENCIES, "Not sure yet") + "</select></div>" +
      "<div><label>Purpose</label><input type=\"text\" class=\"ipur\" placeholder=\"For example, customer and invoice sync\"></div>" +
      "<div class=\"row-actions\"><button type=\"button\" class=\"secondary rmi\">Remove</button></div>";
    $("integrations").appendChild(r);
    r.querySelector(".rmi").onclick = function () { r.remove(); update(); };
  }

  function addLegacy() {
    var r = document.createElement("div");
    r.className = "row legacy";
    r.innerHTML = "<div><label>System</label><input type=\"text\" class=\"lname\"></div>" +
      "<div><label>Purpose</label><input type=\"text\" class=\"lpur\"></div>" +
      "<div><label>Records (estimate)</label><input type=\"number\" class=\"lrec\" min=\"0\"></div>" +
      "<div><label><input type=\"checkbox\" class=\"lret\" checked> Retire after go-live</label></div>" +
      "<div class=\"row-actions\"><button type=\"button\" class=\"secondary rml\">Remove</button></div>";
    $("legacy").appendChild(r);
    r.querySelector(".rml").onclick = function () { r.remove(); update(); };
  }

  function syncNames() {
    var on = $("p_alias").checked;
    document.querySelectorAll(".name-field").forEach(function (f) { f.hidden = on; });
  }

  function systemsList() {
    var names = ["e_crm", "e_erp", "e_tel", "e_mail"].map(function (id) { return $(id).value.trim(); })
      .concat([].map.call(document.querySelectorAll(".lname"), function (x) { return x.value.trim(); }))
      .concat(list($("e_ds").value)).filter(Boolean);
    $("systems").innerHTML = names.filter(function (v, i) { return names.indexOf(v) === i; })
      .map(function (v) { return "<option value=\"" + esc(v) + "\">"; }).join("");
  }

  function checked(cls) { return [].filter.call(document.querySelectorAll("." + cls), function (x) { return x.checked; }).map(function (x) { return x.value; }); }

  function readForm() {
    return {
      org: { name: $("org_name").value, sector: $("org_sector").value, staff: $("org_staff").value, entities: $("org_entities").value,
             countries: $("org_countries").value, regulatory: $("org_reg").value },
      goals: { outcomes: $("g_out").value, measures: $("g_meas").value, goLive: $("g_live").value, budget: $("g_budget").value },
      modules: {
        sales: { on: $("m_sales").checked, users: $("m_sales_u").value },
        marketing: { on: $("m_mkt").checked, users: $("m_mkt_u").value, contacts: $("m_mkt_c").value },
        customer_service: { on: $("m_cs").checked, users: $("m_cs_u").value, channels: checked("cs-ch") },
        field_service: { on: $("m_fs").checked, users: $("m_fs_u").value, technicians: $("m_fs_t").value }
      },
      estate: {
        crm: $("e_crm").value, erp: $("e_erp").value, telephony: $("e_tel").value, email: $("e_mail").value, m365: $("e_m365").checked,
        dataSources: $("e_ds").value, licences: $("e_lic").value, environments: $("e_env").value,
        legacy: [].map.call(document.querySelectorAll(".legacy"), function (r) {
          return { name: r.querySelector(".lname").value, purpose: r.querySelector(".lpur").value,
                   records: r.querySelector(".lrec").value, retire: r.querySelector(".lret").checked };
        }),
        integrations: [].map.call(document.querySelectorAll(".integration"), function (r) {
          return { system: r.querySelector(".isys").value, direction: r.querySelector(".idir").value,
                   frequency: r.querySelector(".ifreq").value, purpose: r.querySelector(".ipur").value };
        })
      },
      team: [].map.call(document.querySelectorAll(".person"), function (p) {
        return { alias: p.querySelector(".alias").value, name: p.querySelector(".pname").value, role: p.querySelector(".role").value,
                 availability: p.querySelector(".avail").value, internal: p.querySelector(".internal").checked,
                 skills: [].map.call(p.querySelectorAll(".skill"), function (s) {
                   return { skill: s.querySelector(".sk").value, level: s.querySelector(".lv").value };
                 }) };
      }),
      constraints: { partner: $("c_partner").checked, partnerScope: $("c_scope").value, compliance: $("c_comp").value,
                     freezes: $("c_freeze").value, risks: $("c_risks").value },
      prefs: { aliases: $("p_alias").checked, edition: $("p_ed").value, formats: checked("fmt") }
    };
  }

  var last = { problems: [] };
  function update() {
    systemsList();
    syncNames();
    var profile = buildProfile(readForm());
    var r = review(profile, VOCAB_IDS);
    var schemaErrors = validate(profile, DATA.schema);
    // The review explains missing outcomes and an empty team in plain words, so skip the schema's version of those.
    var covered = /^(Outcomes|Team): needs at least/;
    last = { problems: r.problems.concat(schemaErrors.filter(function (x) { return !covered.test(x); })), checks: r.checks };
    $("yaml").value = toYaml(profile);
    var html = "";
    if (last.problems.length) {
      html += "<div class=\"check-problems\"><strong>Fix before you use this profile</strong><ul>" +
        last.problems.map(function (x) { return "<li>" + esc(x) + "</li>"; }).join("") + "</ul></div>";
    }
    if (last.checks.length) {
      html += "<div class=\"check-warnings\"><strong>Worth checking</strong><ul>" +
        last.checks.map(function (x) { return "<li>" + esc(x) + "</li>"; }).join("") + "</ul></div>";
    }
    if (!html) html = "<div class=\"check-ok\">The profile is complete and matches the profile format.</div>";
    $("status").innerHTML = html;
  }

  $("addp").onclick = function () { addPerson(); update(); };
  $("addi").onclick = function () { addIntegration(); update(); };
  $("addl").onclick = function () { addLegacy(); update(); };
  $("f").addEventListener("input", function (ev) { if (ev.target.id !== "yaml") update(); });
  $("f").addEventListener("change", function (ev) { if (ev.target.id !== "yaml") update(); });
  $("c_partner").addEventListener("change", function () { $("c_scope_box").hidden = !$("c_partner").checked; });
  $("dl").onclick = function () {
    if (last.problems.length && !window.confirm("This profile has " + last.problems.length +
        " problem(s) that will stop the project pack being built. Download it anyway?")) return;
    var blob = new Blob([$("yaml").value], { type: "text/yaml" });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "organisation-profile.yaml";
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 1000);
  };
  $("copy").onclick = function () {
    $("yaml").select();
    if (navigator.clipboard) navigator.clipboard.writeText($("yaml").value); else document.execCommand("copy");
  };
  addPerson();
  addIntegration();
  update();
})(typeof window !== "undefined" ? window : this);
